"""Español — nivel principiante (200 preguntas)."""

T = {
"prophets_251": ("¿Cómo se llama el Profeta del islam?", ["Muhammad ﷺ", "Ibrahim", "Musa", "Isa"], "El Profeta del islam es Muhammad ﷺ, hijo de 'Abdullah."),
"prophets_252": ("Isma'il e Ishaq son los hijos de qué profeta.", ["Ibrahim", "Musa", "Nuh", "Dawud"], "«Alabado sea Allah, que me ha concedido, a pesar de la vejez, a Isma'il y a Ishaq» (14:39)."),
"prophets_253": ("¿A qué profeta elevó Allah hacia Él?", ["Isa", "Yunus", "Ayyub", "Idris"], "«Al contrario, Allah lo elevó hacia Él» (4:158)."),
"prophets_254": ("¿Quién es la madre del profeta Isa?", ["Maryam", "Asiya", "Hayar", "Sara"], "Maryam, a quien se dedica una sura entera del Corán."),
"prophets_255": ("¿Quién es el primer ser humano que creó Allah?", ["Adam", "Nuh", "Ibrahim", "Idris"], "Adam es el primer hombre, a quien Allah enseñó todos los nombres."),
"prophets_256": ("¿Para qué profeta se volvió el fuego frescor y paz?", ["Ibrahim", "Musa", "Yusuf", "Sulayman"], "«¡Oh fuego, sé frescor y paz para Ibrahim!»"),
"prophets_257": ("¿Qué profeta llevaba un bastón que se convirtió en serpiente?", ["Musa", "Harun", "Yahya", "Zakariyya"], "Allah preguntó a Musa: «¿Y qué es eso que tienes en tu mano derecha?»"),
"prophets_258": ("¿Qué profeta soñó con once estrellas que se postraban?", ["Yusuf", "Ya'qub", "Ishaq", "Dawud"], "«¡Padre mío! He visto once estrellas, el sol y la luna.»"),
"prophets_259": ("¿Qué ave trajo noticias al profeta Sulayman?", ["La abubilla", "El cuervo", "El halcón", "La paloma"], "La abubilla dijo: «Te traigo de Saba una noticia cierta» (27:22)."),
"prophets_260": ("¿Qué profeta es el modelo de paciencia en la prueba?", ["Ayyub", "Yunus", "Lut", "Shu'ayb"], "Ayyub invocó a su Señor y se mostró firme y paciente."),
"prophets_261": ("¿De qué creó Allah a Adam?", ["De polvo", "De luz", "De fuego", "De viento"], "«Lo creó de polvo y luego le dijo: ¡Sé!» (3:59)."),
"prophets_262": ("¿A qué profeta le habló Allah directamente?", ["Musa", "Yusuf", "Yunus", "Salih"], "«Y Allah habló a Musa directamente.»"),
"prophets_263": ("¿Cuántos profetas vienen después de Muhammad ﷺ?", ["Ninguno: él es el último de los profetas", "Uno", "Tres", "Siete"], "Muhammad ﷺ es el sello de los profetas: ningún profeta viene después de él."),
"prophets_264": ("¿Qué profeta es llamado el amigo íntimo (jalil) de Allah?", ["Ibrahim", "Musa", "Isa", "Nuh"], "Ibrahim es el padre de los profetas y el amigo íntimo del Misericordioso."),
"prophets_265": ("¿Qué profeta curó al ciego de nacimiento con el permiso de Allah?", ["Isa", "Yahya", "Zakariyya", "Ilyas"], "«Y curabas al ciego de nacimiento y al leproso con Mi permiso.»"),
"prophets_266": ("¿Con qué profeta repetían las montañas la alabanza de Allah?", ["Dawud", "Sulayman", "Ayyub", "Yunus"], "«¡Oh montañas, repetid con él las alabanzas de Allah!»"),
"prophets_267": ("¿Qué profeta explicó el sueño del rey de Egipto?", ["Yusuf", "Harun", "Ilyas", "Shu'ayb"], "Yusuf explicó el sueño de las siete vacas gordas y las siete flacas (12:46-49)."),
"prophets_268": ("¿Quién es el padre del profeta Yusuf?", ["Ya'qub", "Ishaq", "Ibrahim", "Lut"], "Yusuf es hijo de Ya'qub, que a su vez es hijo de Ishaq."),
"prophets_269": ("¿Qué se abrió ante Musa y su pueblo?", ["El mar, que se abrió para salvarlos del Faraón", "Un río de Egipto", "Un lago de Madyan", "Un pozo del desierto"], "«Y cuando abrimos el mar para vosotros y os salvamos.»"),
"prophets_270": ("¿Qué se dice después de mencionar el nombre del Profeta ﷺ?", ["«Que Allah lo bendiga y le dé paz»", "Nada en particular", "«Gracias»", "«Adiós»"], "Se pide para él la bendición y la paz: salla-Llahu 'alayhi wa sallam."),
"prophets_271": ("¿Qué profeta llamó a su pueblo durante muchísimo tiempo antes del diluvio?", ["Nuh", "Hud", "Salih", "Shu'ayb"], "«Enviamos a Nuh a su pueblo: advierte a tu pueblo.»"),
"prophets_272": ("Sulayman es hijo de qué profeta.", ["Dawud", "Ya'qub", "Ishaq", "Yunus"], "«Y a Dawud le dimos a Sulayman. ¡Qué excelente siervo!» (38:30)."),
"prophets_273": ("¿Qué profeta venció a Yalut (Goliat)?", ["Dawud", "Sulayman", "Yusha'", "Ilyas"], "«Y Dawud mató a Yalut» (2:251)."),
"prophets_274": ("¿En cuántos profetas debe creer un musulmán?", ["En todos, sin hacer distinción", "Solo en el último", "Solo en tres", "Solo en los que nombra el Corán"], "El musulmán cree en todos los profetas de Allah, sin hacer distinción entre ellos."),
"prophets_275": ("¿A quiénes eligió Allah, según el Corán?", ["A Adam, a Nuh, a la familia de Ibrahim y a la familia de 'Imran", "A los reyes de Egipto", "A las tribus de Medina", "Al pueblo de Saba"], "«Allah eligió a Adam, a Nuh, a la familia de Ibrahim y a la familia de 'Imran.»"),
"prophets_276": ("¿En qué tierra se ganó el profeta Yusuf la confianza del rey?", ["Egipto", "Sham", "Yemen", "Irak"], "Yusuf se estableció en Egipto tras interpretar el sueño del rey."),
"prophets_277": ("¿Qué profeta fue llevado de noche a la mezquita de Al-Aqsa?", ["Muhammad ﷺ", "Musa", "Isa", "Ibrahim"], "«Gloria a Quien hizo viajar de noche a Su siervo.»"),
"prophets_278": ("¿Qué libro se le dio al profeta Musa?", ["La Torá", "El Evangelio", "Los Salmos", "Las Hojas de Ibrahim"], "Allah dio a Musa el Libro y, después de él, envió mensajeros."),
"prophets_279": ("¿Qué libro se le dio al profeta Isa?", ["El Evangelio", "La Torá", "Los Salmos", "El Corán"], "«Y le dimos el Evangelio, en el que hay guía y luz.»"),
"prophets_280": ("¿Qué libro se le dio al profeta Dawud?", ["Los Salmos (Zabur)", "La Torá", "El Evangelio", "Las Hojas de Musa"], "«Y a Dawud le dimos el Zabur.»"),
"prophets_281": ("¿El hijo de qué profeta aceptó ser sacrificado por obediencia a Allah?", ["El hijo de Ibrahim", "El hijo de Nuh", "El hermano de Musa", "El hijo de Ya'qub"], "«¡Padre mío! Haz lo que se te ordena: me encontrarás paciente.»"),
"prophets_282": ("¿Dónde puso la madre de Musa a su bebé para salvarlo?", ["En el río", "En una cueva", "Con una vecina", "En el desierto"], "«Échalo al río: te lo devolveremos.»"),
"prophets_283": ("¿Qué dijo Yunus en las tinieblas, palabras que todo musulmán repite?", ["«No hay dios sino Tú, gloria a Ti, he sido de los injustos»", "«Dame riquezas»", "«Hazme rey»", "«Hazme fuerte»"], "La súplica de Yunus dentro del pez."),
"prophets_284": ("¿Quién es el padre del Profeta Muhammad ﷺ?", ["'Abdullah", "Abu Talib", "Al-'Abbas", "Hamza"], "Él es Muhammad ﷺ, hijo de 'Abdullah, hijo de 'Abd al-Muttalib."),
"prophets_285": ("¿Quién es la madre del Profeta Muhammad ﷺ?", ["Amina", "Jadiya", "Aisha", "Fátima"], "Amina bint Wahb es la madre del Profeta ﷺ."),
"prophets_286": ("¿Qué dijo Isa cuando aún estaba en la cuna?", ["«Soy el siervo de Allah»", "«Soy un rey»", "«Soy un ángel»", "No dijo nada"], "«Ciertamente, soy el siervo de Allah: Él me ha dado la Escritura.»"),
"prophets_287": ("¿Qué profeta fue enviado al pueblo de 'Ad?", ["Hud", "Salih", "Lut", "Shu'ayb"], "«Y a 'Ad, a su hermano Hud.»"),
"prophets_288": ("¿Qué profeta fue enviado a Zamud, con la camella?", ["Salih", "Hud", "Yunus", "Idris"], "«Y a Zamud, a su hermano Salih: esta es la camella de Allah.»"),
"prophets_289": ("¿Qué profeta es el hermano de Musa, enviado junto a él?", ["Harun", "Yusuf", "Yahya", "Ilyas"], "«Y dame un ayudante de mi familia: Harun, mi hermano.»"),
"prophets_290": ("¿Qué título da el Corán a Muhammad ﷺ respecto a los profetas?", ["El sello de los profetas", "El primero de los profetas", "El rey de los profetas", "El escriba de los profetas"], "«Muhammad es el Mensajero de Allah y el sello de los profetas.»"),
"prophets_291": ("¿Qué dicen los ángeles a Maryam en el Corán?", ["Que Allah la ha elegido y purificado", "Que será reina", "Que viajará", "Que enseñará"], "«¡Oh Maryam! Allah te ha elegido y te ha purificado.»"),
"prophets_292": ("¿Cómo invocó Ayyub a su Señor en su prueba?", ["«Me ha alcanzado la desgracia, y Tú eres el más misericordioso»", "«Hazme rico»", "«Castiga a mis enemigos»", "«Hazme rey»"], "«Me ha alcanzado la desgracia, y Tú eres el más misericordioso de los misericordiosos.»"),
"prophets_293": ("¿Qué enseñó Allah a Adam?", ["Todos los nombres", "La escritura", "La navegación", "La aritmética"], "«Y enseñó a Adam todos los nombres.»"),
"prophets_294": ("¿Qué profeta gobernó un reino que nadie tendría después de él?", ["Sulayman", "Dawud", "Yusuf", "Dhul-Qarnayn"], "«Concédeme un reino que nadie tenga después de mí.»"),
"prophets_295": ("¿Qué profeta fue salvado con su familia, excepto su esposa?", ["Lut", "Nuh", "Hud", "Salih"], "«Sal con tu familia al final de la noche… excepto tu esposa.»"),
"prophets_296": ("¿Contra qué advirtió Ibrahim a su pueblo?", ["Contra adorar ídolos", "Contra comerciar", "Contra viajar", "Contra escribir"], "«¿Tomáis ídolos como dioses?»"),
"prophets_297": ("¿Qué palabra designa a alguien enviado por Allah a la humanidad?", ["Un mensajero (rasul)", "Un califa", "Un compañero", "Un sabio"], "Un rasul es un enviado de Allah, encargado de un mensaje para la humanidad."),
"prophets_298": ("¿Como qué envió Allah al Profeta ﷺ, según la sura Al-Ahzab?", ["Como testigo, anunciador de buenas noticias y advertidor", "Como rey y juez", "Como comerciante", "Como poeta"], "«¡Oh Profeta! Te hemos enviado como testigo, anunciador de buenas noticias y advertidor» (33:45)."),
"prophets_299": ("¿Por qué fue enviado Muhammad ﷺ, según el Corán?", ["Como misericordia para los mundos", "Para gobernar", "Para construir", "Para comerciar"], "«Y no te hemos enviado sino como misericordia para los mundos.»"),
"prophets_300": ("¿A qué profeta llama el Corán «un siervo muy agradecido»?", ["Nuh", "Lut", "Idris", "Ilyas"], "«Ciertamente, fue un siervo agradecido» (17:3), dicho de Nuh."),
"prophets_301": ("¿Qué señal recibió Zakariyya tras la noticia de su hijo?", ["No hablar a la gente durante tres días", "Ver una estrella", "Oír un trueno", "Caminar sobre el agua"], "«Tu señal será que no hablarás a la gente durante tres días» (3:41)."),
"prophets_302": ("¿En qué lengua fue enviado cada mensajero?", ["En la lengua de su propio pueblo", "Solo en árabe", "En hebreo", "En una lengua celestial"], "«No hemos enviado ningún mensajero sino en la lengua de su pueblo.»"),
"prophets_303": ("¿Qué sura cuenta la historia de un profeta de principio a fin?", ["La sura Yusuf", "La sura Al-Baqara", "La sura An-Nas", "La sura Al-Fatiha"], "«Te contamos la más bella de las historias»: la historia de Yusuf."),
"prophets_304": ("¿Cómo describe el Corán a Ibrahim en la sura Maryam?", ["Un hombre veraz, un profeta", "Un rey", "Un escriba", "Un comerciante"], "«Fue un hombre veraz, un profeta.»"),
"prophets_305": ("¿Qué reina fue a ver al profeta Sulayman?", ["La reina de Saba", "La reina de Egipto", "La reina de Babilonia", "La reina del norte de Yemen"], "Ella se sometió, junto con Sulayman, a Allah, Señor de los mundos."),
"prophets_306": ("¿Qué profeta pidió ver cómo Allah devuelve la vida?", ["Ibrahim", "Musa", "Nuh", "Yunus"], "«¡Señor mío! Muéstrame cómo das vida a los muertos.»"),
"prophets_307": ("¿Qué profeta viajó para aprender de un siervo sabio?", ["Musa", "Yusuf", "Dawud", "Sulayman"], "Musa viajó hasta encontrar a un siervo de Allah al que Él había dado conocimiento."),
"prophets_308": ("¿Qué enseña la sura Al-Ijlas sobre Allah?", ["Que Él es Uno, y nadie es igual a Él", "Que tiene asociados", "Que se parece a Su creación", "Que tiene un hijo"], "«Di: Él es Allah, Uno… y no hay nadie comparable a Él.»"),
"prophets_309": ("¿Cómo llamaban los mecanos al Profeta ﷺ antes de la revelación?", ["Al-Amin, el digno de confianza", "El viajero", "El poeta", "El juez"], "Su rectitud era tan conocida que lo llamaban al-Amin."),
"prophets_310": ("¿A quién presenta el Corán como el mejor ejemplo a seguir?", ["Al Mensajero de Allah ﷺ", "A los reyes", "A los poetas", "A los comerciantes"], "«Ciertamente, tenéis en el Mensajero de Allah un bello ejemplo.»"),
"sira_251": ("¿En qué ciudad nació el Profeta ﷺ?", ["La Meca", "Medina", "Jerusalén", "Ta'if"], "El Profeta ﷺ nació en La Meca, en la tribu de Quraysh."),
"sira_252": ("¿A qué ciudad emigró el Profeta ﷺ?", ["Medina", "Ta'if", "El Cairo", "Damasco"], "La Hégira fue de La Meca a Medina, llamada entonces Yazrib."),
"sira_253": ("¿Cómo se llama el traslado de La Meca a Medina?", ["La Hégira", "La peregrinación", "La conquista", "El pacto"], "La Hégira marca el comienzo del calendario musulmán."),
"sira_254": ("¿Quién es la primera esposa del Profeta ﷺ?", ["Jadiya", "Aisha", "Hafsa", "Sawda"], "Jadiya bint Juwaylid, la primera en creer en él."),
"sira_255": ("¿En qué cueva se escondió el Profeta ﷺ durante la Hégira?", ["La cueva de Zawr", "La cueva de Hira", "La cueva de Uhud", "La cueva de Quba"], "Se escondió allí tres días con Abu Bakr antes de seguir el camino hacia Medina."),
"sira_256": ("¿Cuál es la primera palabra revelada al Profeta ﷺ?", ["«Lee»", "«Reza»", "«Levántate»", "«Escucha»"], "«Lee, en el nombre de tu Señor, que ha creado.»"),
"sira_257": ("¿Qué ángel trajo la revelación al Profeta ﷺ?", ["Yibril", "Mika'il", "Israfil", "Malik"], "Yibril es el ángel encargado de hacer descender la revelación."),
"sira_258": ("¿En qué ciudad está la tumba del Profeta ﷺ?", ["Medina", "La Meca", "Jerusalén", "Ta'if"], "Su tumba está en Medina, junto a su mezquita."),
"sira_259": ("¿De qué tribu era el Profeta ﷺ?", ["Quraysh", "Aws", "Jazray", "Zaqif"], "El Profeta ﷺ era de Quraysh, la tribu de La Meca."),
"sira_260": ("¿Cómo se llama a los compañeros del Profeta ﷺ?", ["Los Sahaba", "Los Tabi'un", "Solo los Ansar", "Los Qurra"], "Los Sahaba son quienes vieron al Profeta ﷺ creyendo en él."),
"sira_261": ("¿Quién acompañó al Profeta ﷺ en la Hégira?", ["Abu Bakr", "Umar", "Uzman", "Bilal"], "Abu Bakr fue su compañero en la cueva durante la Hégira."),
"sira_262": ("¿Quién hacía la llamada a la oración para el Profeta ﷺ?", ["Bilal", "Anas", "Zayd", "Salman"], "Bilal ibn Rabah llamaba a la oración en Medina."),
"sira_263": ("¿Cómo se llama la primera batalla del islam?", ["Badr", "Uhud", "Jaybar", "Hunayn"], "Badr es la primera gran batalla, en el segundo año de la Hégira."),
"sira_264": ("¿Cómo se llama a quienes emigraron de La Meca a Medina?", ["Los Muhayirun", "Los Ansar", "Los Tabi'un", "Los compañeros de Ta'if"], "Los Muhayirun son los emigrados; los Ansar, quienes los acogieron."),
"sira_265": ("¿Cómo se llama a la gente de Medina que acogió a los emigrados?", ["Los Ansar", "Los Muhayirun", "Quraysh", "Los Tabi'un"], "Los Ansar, «los auxiliares», son los Aws y los Jazray de Medina."),
"sira_266": ("¿Qué construyó primero el Profeta ﷺ en Medina?", ["Una mezquita", "Un mercado", "Un palacio", "Una muralla"], "Construyó su mezquita nada más llegar a Medina."),
"sira_267": ("¿Qué hija del Profeta ﷺ se casó con Ali?", ["Fátima", "Ruqayya", "Zaynab", "Umm Kulzum"], "Fátima, hija del Profeta ﷺ, se casó con Ali ibn Abi Talib."),
"sira_268": ("¿Quién fue el primer califa después del Profeta ﷺ?", ["Abu Bakr", "Umar", "Uzman", "Ali"], "Abu Bakr as-Siddiq fue el primer califa."),
"sira_269": ("¿Cómo se llamaba Medina antes?", ["Yazrib", "Bakka", "Ta'if", "Jaybar"], "Yazrib tomó el nombre de Madinat an-Nabi, la ciudad del Profeta ﷺ."),
"sira_270": ("¿Qué edad tenía el Profeta ﷺ en la primera revelación?", ["Cuarenta años", "Veinte", "Sesenta", "Treinta"], "La revelación le llegó cuando tenía cuarenta años."),
"sira_271": ("¿En qué ciudad está la Ka'ba?", ["La Meca", "Medina", "Jerusalén", "Damasco"], "La Ka'ba se alza en el centro de la Mezquita Sagrada, en La Meca."),
"sira_272": ("¿En qué ciudad está la mezquita de Al-Aqsa?", ["Jerusalén", "La Meca", "Medina", "El Cairo"], "La mezquita de Al-Aqsa está en Jerusalén (al-Quds)."),
"sira_273": ("¿Qué tío del Profeta ﷺ lo protegió en La Meca?", ["Abu Talib", "Abu Lahab", "Al-'Abbas", "Abu Sufyan"], "Abu Talib, el padre de Ali, protegió a su sobrino frente a Quraysh."),
"sira_274": ("¿Cuál era el oficio de Jadiya, la primera esposa del Profeta ﷺ?", ["Comerciante", "Médica", "Poetisa", "Tejedora"], "Jadiya era una comerciante respetada de La Meca."),
"sira_275": ("¿Cómo se llama la última peregrinación del Profeta ﷺ?", ["La Peregrinación de Despedida", "La primera peregrinación", "La peregrinación de la conquista", "La peregrinación menor"], "La Peregrinación de Despedida tuvo lugar en el año 10 de la Hégira."),
"sira_276": ("¿Cómo se llama el relato de la vida del Profeta ﷺ?", ["La Sira", "La Sunna", "El Tafsir", "El Fiqh"], "La Sira es el relato de su vida; la Sunna es lo que dijo e hizo."),
"sira_277": ("¿Cómo se llama un dicho transmitido del Profeta ﷺ?", ["Un hadiz", "Una sura", "Una aleya", "Una súplica"], "Un hadiz es un dicho, un acto o una aprobación del Profeta ﷺ."),
"sira_278": ("¿Qué dos colecciones de hadices se consideran las más rigurosas?", ["Sahih al-Bujari y Sahih Muslim", "Dos colecciones de poesía", "Dos libros de historia", "Dos diccionarios"], "Juntas se las llama «los dos Sahih»."),
"sira_279": ("¿Qué califa mandó copiar el Corán y enviarlo a las provincias?", ["Uzman", "Abu Bakr", "Umar", "Ali"], "Uzman mandó hacer copias oficiales y enviarlas a las principales ciudades."),
"sira_280": ("¿Cuántos son «los califas bien guiados»?", ["Cuatro", "Dos", "Siete", "Doce"], "Abu Bakr, Umar, Uzman y Ali."),
"sira_281": ("¿Hacia dónde rezan los musulmanes?", ["Hacia la Ka'ba, en La Meca", "Hacia Jerusalén", "Hacia el este", "Hacia Medina"], "La qibla es la dirección de la Ka'ba."),
"sira_282": ("¿Cómo se llama esa dirección de la oración?", ["La qibla", "El mihrab", "El minbar", "El minarete"], "La qibla es la dirección; el mihrab es el nicho que la señala."),
"sira_283": ("¿Cómo se llama el lugar donde los musulmanes rezan juntos?", ["La mezquita", "La escuela", "El mercado", "La biblioteca"], "El masyid es el lugar de la postración: la mezquita."),
"sira_284": ("¿Cómo se llama la llamada a la oración?", ["El adhan", "El takbir", "El tasbih", "El dhikr"], "El adhan es la llamada; quien la hace es el almuédano (muecín)."),
"sira_285": ("¿Qué día se reúnen los musulmanes para la gran oración?", ["El viernes", "El sábado", "El domingo", "El lunes"], "La oración del viernes (al-yumu'a) reúne a la comunidad cada semana."),
"sira_286": ("¿Cómo se llama la persona que dirige la oración?", ["El imam", "El almuédano", "El juez", "El hafiz"], "El imam es aquel detrás del cual se alinean los fieles para rezar."),
"sira_287": ("¿Cómo se llama a quien ha memorizado todo el Corán?", ["Un hafiz", "Un imam", "Un almuédano", "Un juez"], "Un hafiz es quien guarda todo el Corán en su memoria."),
"sira_288": ("¿Qué compañero es conocido como el mayor transmisor de hadices?", ["Abu Hurayra", "Bilal", "Salman", "Anas"], "Abu Hurayra pasó los últimos años del Profeta ﷺ a su lado."),
"sira_289": ("¿Qué califa es llamado as-Siddiq, «el veraz»?", ["Abu Bakr", "Umar", "Uzman", "Ali"], "Abu Bakr as-Siddiq, el primer hombre libre en creer."),
"sira_290": ("¿Qué califa es llamado al-Faruq?", ["Umar ibn al-Jattab", "Abu Bakr", "Uzman", "Ali"], "Umar, que distinguió la verdad de la falsedad, recibió ese título."),
"sira_291": ("¿Qué califa mandó reunir el Corán en un solo volumen?", ["Abu Bakr", "Mu'awiya", "Jalid", "Bilal"], "Abu Bakr ordenó reunir todo lo que se había puesto por escrito."),
"sira_292": ("¿Qué abuelo crio al Profeta ﷺ de niño?", ["'Abd al-Muttalib", "Abu Sufyan", "Al-Walid", "'Utba"], "Su abuelo 'Abd al-Muttalib se hizo cargo de él tras su nacimiento."),
"sira_293": ("¿Cómo recuerda el Corán la infancia del Profeta ﷺ?", ["Allah lo encontró huérfano y le dio refugio", "Era un rey", "Fue rico desde niño", "Vivía solo en el desierto"], "«¿Acaso no te encontró huérfano y te dio refugio?» (93:6)."),
"sira_294": ("¿Qué batalla vino después de Badr?", ["Uhud", "La Trinchera", "Hunayn", "Tabuk"], "Al año siguiente tuvo lugar la batalla de Uhud, cerca de Medina."),
"sira_295": ("¿Qué cavaron los musulmanes alrededor de Medina para defenderla?", ["Una trinchera (al-Jandaq)", "Un pozo", "Un túnel", "Un canal"], "Cavaron una trinchera, que dio su nombre a la batalla de la Trinchera."),
"sira_296": ("¿De quién era hija Aisha, la esposa del Profeta ﷺ?", ["De Abu Bakr", "De Umar", "De Uzman", "De Ali"], "Aisha era hija de Abu Bakr as-Siddiq."),
"sira_297": ("¿Cómo llama el Corán a las esposas del Profeta ﷺ?", ["Las madres de los creyentes", "Las sirvientas", "Las compañeras de viaje", "Las emigradas"], "«Y sus esposas son las madres de ellos» (33:6)."),
"sira_298": ("¿Qué compañero fue a la vez primo y yerno del Profeta ﷺ?", ["Ali ibn Abi Talib", "Bilal", "Salman", "Zayd"], "Ali, primo del Profeta ﷺ, se casó con su hija Fátima."),
"sira_299": ("¿Cómo se llama la mezquita del Profeta ﷺ en Medina?", ["Al-Masyid an-Nabawi", "Al-Masyid al-Haram", "Al-Aqsa", "Quba"], "La Mezquita del Profeta, an-Nabawi, se alza en Medina."),
"sira_300": ("¿Cómo se llama la montura del viaje nocturno del Profeta ﷺ?", ["Al-Buraq", "Al-'Adba'", "Ash-Shaqra'", "Al-Qaswa'"], "La montura del viaje nocturno se llama al-Buraq."),
"faith_151": ("¿Cuántos pilares tiene el islam?", ["Cinco", "Tres", "Seis", "Diez"], "Cinco: el testimonio de fe, la oración, el zakat, el ayuno y la peregrinación."),
"faith_152": ("¿Cuál es el primer pilar del islam?", ["El testimonio de fe (shahada)", "El ayuno", "La peregrinación", "El zakat"], "Se entra en el islam atestiguando que no hay dios sino Allah y que Muhammad ﷺ es Su mensajero."),
"faith_153": ("¿Cuántas oraciones obligatorias hace un musulmán cada día?", ["Cinco", "Tres", "Siete", "Dos"], "Cinco oraciones, repartidas desde el alba hasta la noche."),
"faith_154": ("¿En qué mes ayunan los musulmanes?", ["Ramadán", "Rayab", "Sha'ban", "Shawwal"], "«El mes de Ramadán, en el que fue revelado el Corán» (2:185)."),
"faith_155": ("¿Cómo se llama la limosna obligatoria del islam?", ["Zakat", "Du'a", "Dhikr", "Tawaf"], "El zakat es la parte de los bienes que se entrega cada año."),
"faith_156": ("¿Cómo se llama la peregrinación mayor a La Meca?", ["El hayy", "El sa'i", "El dhikr", "El suhur"], "El hayy es la peregrinación que hace una vez en la vida quien puede."),
"faith_157": ("¿Cuántos artículos de fe (arkan al-iman) hay?", ["Seis", "Cuatro", "Cinco", "Siete"], "Creer en Allah, en Sus ángeles, en Sus libros, en Sus mensajeros, en el Último Día y en el destino."),
"faith_158": ("¿En cuántos dioses cree un musulmán?", ["Solo en uno", "En dos", "En tres", "En muchos"], "«Di: Él es Allah, Uno» (112:1)."),
"faith_159": ("¿Cómo llaman los musulmanes a Dios en árabe?", ["Allah", "Malak", "Rasul", "Nabi"], "Allah es el nombre del Creador en árabe."),
"faith_160": ("¿Cómo se llama el libro sagrado de los musulmanes?", ["El Corán", "La Tawrat", "El Inyil", "El Zabur"], "El Corán es el libro revelado al Profeta Muhammad ﷺ."),
"faith_161": ("¿Cómo se llama la Casa de Allah construida en La Meca?", ["La Ka'ba", "La Rawda", "El Maqam", "El Hiyr"], "«La primera Casa establecida para los hombres es la de Bakka» (3:96)."),
"faith_162": ("¿Qué dice un musulmán antes de empezar a comer?", ["Bismillah", "Amin", "Subhan Allah", "Allahumma"], "El Profeta ﷺ enseñó a un niño: «Di Bismillah y come con la mano derecha»."),
"faith_163": ("¿Cómo se saludan los musulmanes?", ["As-salamu alaykum", "Al-hamdu lillah", "Bismillah", "Allahu akbar"], "«As-salamu alaykum» significa: la paz sea con vosotros."),
"faith_164": ("¿Cómo se responde a «as-salamu alaykum»?", ["Wa alaykum as-salam", "Bismillah", "Amin", "Subhan Allah"], "Se devuelve el saludo: «y con vosotros sea la paz»."),
"faith_165": ("¿Cómo se llama la fiesta que viene justo después del mes de Ramadán?", ["Eid al-Fitr", "Eid al-Adha", "Laylat al-Qadr", "Ashura"], "El Eid al-Fitr, la fiesta de la ruptura del ayuno."),
"faith_166": ("¿Cómo se llama la fiesta del sacrificio?", ["Eid al-Adha", "Eid al-Fitr", "El Mawlid", "Laylat al-Qadr"], "El Eid al-Adha cae durante los días de la peregrinación."),
"faith_167": ("¿Cómo se llaman las criaturas de Allah que siempre Le obedecen y nunca Le desobedecen?", ["Los ángeles", "Los genios", "Los profetas", "Los compañeros"], "Los ángeles cumplen lo que Allah ordena y nunca Le desobedecen."),
"faith_168": ("¿Cómo se llama el Paraíso en árabe?", ["Al-Yanna", "As-Salat", "Ad-Du'a", "Al-Adhan"], "Al-Yanna, literalmente «el jardín», es la morada prometida a los creyentes."),
"faith_169": ("¿Cómo se llama el lavado con agua que se hace antes de rezar?", ["La ablución (wudu)", "El tawaf", "El dhikr", "El sa'i"], "El wudu es la purificación que precede a la oración."),
"faith_170": ("¿Cómo se llama una unidad de la oración?", ["Una rak'a", "Una sura", "Un adhan", "Un tawaf"], "Una rak'a incluye estar de pie, la inclinación y las postraciones."),
"faith_171": ("¿Qué sura se recita en cada unidad de la oración?", ["Al-Fatiha", "Al-Ijlas", "An-Nas", "Al-Kawzar"], "Al-Fatiha, la sura de apertura, se recita en cada rak'a."),
"faith_172": ("¿Cómo se llama lo que está permitido en el islam?", ["Halal", "Haram", "Sunna", "Fard"], "Halal significa lo que es lícito."),
"faith_173": ("¿Cómo se llama lo que está prohibido en el islam?", ["Haram", "Halal", "Mubah", "Nafila"], "Haram significa lo que es ilícito."),
"faith_174": ("¿Qué carne prohíbe el Corán?", ["La de cerdo", "La de cordero", "La de vaca", "La de pollo"], "«Os ha prohibido la carroña, la sangre y la carne de cerdo» (2:173)."),
"faith_175": ("¿Qué bebida nos ordena evitar el Corán?", ["El vino y todo lo que embriaga", "La leche", "La miel", "El agua de lluvia"], "«El vino, el juego de azar… son una abominación: evitadlos» (5:90)."),
"faith_176": ("¿Qué dice quien estornuda, como enseñó el Profeta ﷺ?", ["Al-hamdu lillah", "Bismillah", "Allahu akbar", "Amin"], "«Cuando uno de vosotros estornude, que diga: al-hamdu lillah.»"),
"faith_177": ("¿Cómo se dice «la oración» en árabe?", ["As-salat", "As-sawm", "Az-zakat", "Al-hayy"], "As-salat es la oración ritual del musulmán."),
"faith_178": ("¿Cómo se llama pedir algo a Allah con tus propias palabras?", ["Du'a", "Tawaf", "Adhan", "Sa'i"], "El du'a es la súplica: invocar a Allah."),
"faith_179": ("¿Qué significa «al-hamdu lillah»?", ["Alabado sea Allah", "Allah es el más grande", "En el nombre de Allah", "Gloria a Allah"], "Es la segunda aleya de Al-Fatiha: «Alabado sea Allah, Señor de los mundos» (1:2)."),
"faith_180": ("¿Qué significa la palabra «islam»?", ["Sumisión a Allah", "Riqueza", "Viaje", "Conocimiento"], "Islam viene de una raíz que significa someterse y estar en paz."),
"faith_181": ("¿Qué significa la palabra «musulmán»?", ["El que se somete a Allah", "El que viaja", "El que enseña", "El que construye"], "Un musulmán es quien se somete solo a Allah."),
"faith_182": ("¿Quién creó los cielos y la tierra, según el Corán?", ["Allah", "Los ángeles", "Los profetas", "El sol"], "«Alabado sea Allah, que creó los cielos y la tierra» (6:1)."),
"faith_183": ("¿Cuántos nombres de Allah menciona el hadiz?", ["Noventa y nueve", "Diez", "Cincuenta", "Mil"], "«Allah tiene noventa y nueve nombres, cien menos uno.»"),
"faith_184": ("¿Qué hacen los ángeles llamados «nobles escribas»?", ["Escriben nuestras obras", "Traen la lluvia", "Guardan la Ka'ba", "Enseñan árabe"], "«Nobles escribas, que saben lo que hacéis» (82:11-12)."),
"faith_185": ("¿Qué noche describe el Corán como mejor que mil meses?", ["Laylat al-Qadr", "La noche del viernes", "La noche del Eid", "La primera noche de Ramadán"], "«La Noche del Decreto es mejor que mil meses» (97:3)."),
"faith_186": ("¿Cómo se llama creer en un solo Dios?", ["Tawhid", "Tawaf", "Tayammum", "Tarawih"], "El tawhid es la unicidad de Allah, el corazón del mensaje de todos los profetas."),
"faith_187": ("¿Cómo se llama asociar a alguien con Allah en la adoración?", ["Shirk", "Dhikr", "Du'a", "Sabr"], "El shirk es la asociación: adorar algo junto a Allah."),
"faith_188": ("¿Cómo se llama el día en que todos serán juzgados?", ["El Día de la Resurrección", "El día del Eid", "El viernes", "El primer día de Ramadán"], "Yawm al-Qiyama, el Día de la Resurrección, cuando cada uno verá sus obras."),
"faith_189": ("¿Cuántos meses tiene el año según el Corán?", ["Doce", "Diez", "Catorce", "Seis"], "«El número de meses para Allah es doce» (9:36)."),
"faith_190": ("¿Cuántas postraciones hay en una sola rak'a?", ["Dos", "Una", "Tres", "Cuatro"], "Cada rak'a incluye dos postraciones."),
"quran_151": ("¿Cuántas suras tiene el Corán?", ["Ciento catorce", "Sesenta", "Doscientas", "Treinta"], "El Corán tiene 114 suras, desde Al-Fatiha hasta An-Nas."),
"quran_152": ("¿Cuál es la primera sura del Corán?", ["Al-Fatiha", "Al-Baqara", "An-Nas", "Ya-Sin"], "Al-Fatiha, «la apertura», es la primera sura."),
"quran_153": ("¿Qué significa la palabra «Corán»?", ["La recitación, la lectura", "El camino", "La luz", "El jardín"], "Corán viene de una raíz que significa leer y recitar."),
"quran_154": ("¿Durante cuántos años, aproximadamente, fue revelado el Corán?", ["Unos veintitrés años", "Una sola noche", "Cien años", "Tres años"], "La revelación descendió a lo largo de unos veintitrés años."),
"quran_155": ("¿Cómo se llama un versículo del Corán?", ["Una aleya", "Una sura", "Un yuz'", "Un hadiz"], "Cada frase numerada del Corán es una aleya, un «signo»."),
"quran_156": ("¿Cómo se llama un capítulo del Corán?", ["Una sura", "Una aleya", "Un yuz'", "Una jutba"], "El Corán se divide en suras, cada una con su propio nombre."),
"quran_157": ("¿Cuál es la sura más larga del Corán?", ["Al-Baqara", "Al-Fatiha", "Al-Kawzar", "An-Nas"], "Al-Baqara es la sura más larga del Corán."),
"quran_158": ("¿Cuál es la sura más corta del Corán?", ["Al-Kawzar", "Al-Baqara", "Al 'Imran", "An-Nisa"], "Al-Kawzar tiene solo tres aleyas."),
"quran_159": ("¿Qué frase abre casi todas las suras?", ["En el nombre de Allah, el Misericordioso, el Compasivo", "Alabado sea Allah", "Allah es el más grande", "No hay dios sino Allah"], "La basmala abre 113 de las 114 suras."),
"quran_160": ("¿De quién es la palabra el Corán?", ["De Allah", "Del Profeta ﷺ", "Del ángel Yibril", "De los compañeros"], "El Corán se llama a sí mismo «la palabra de Allah» (kalam Allah) en 9:6."),
"quran_161": ("¿En cuántas partes (yuz') se divide el Corán?", ["Treinta", "Diez", "Cincuenta", "Cien"], "El Corán se divide en treinta yuz', uno por cada noche de Ramadán."),
"quran_162": ("¿Qué sura lleva el nombre de una mujer?", ["Maryam", "Yusuf", "Nuh", "Muhammad"], "La sura 19 lleva el nombre de Maryam."),
"quran_163": ("¿Cómo se llaman las dos últimas suras, con las que se busca refugio?", ["Al-Mu'awwidhatan", "Al-Mazani", "Al-Mufassal", "Al-Hawamim"], "Al-Falaq y An-Nas se llaman al-Mu'awwidhatan, «las dos protectoras»."),
"quran_164": ("¿Qué palabra abre la sura Al-Fatiha, después de la basmala?", ["Al-hamdu", "Qul", "Iqra'", "Inna"], "«Al-hamdu lillahi rabbi l-'alamin» abre Al-Fatiha."),
"quran_165": ("¿Cómo se llama la explicación del significado del Corán?", ["Tafsir", "Taywid", "Hifz", "Tawaf"], "El tafsir es la ciencia que explica el significado de las aleyas."),
"quran_166": ("¿Qué sura no empieza con la basmala?", ["At-Tawba", "Al-Fatiha", "Al-Ijlas", "An-Nasr"], "At-Tawba es la única sura que no comienza con la basmala."),
"quran_167": ("¿Cómo se llama a quien recita el Corán en voz alta?", ["Un qari'", "Un almuédano", "Un imam", "Un jatib"], "El qari' es el recitador del Corán."),
"quran_168": ("¿En qué sura se encuentra el Versículo del Trono?", ["Al-Baqara", "Al-Kahf", "Ya-Sin", "Al-Mulk"], "El Versículo del Trono es la aleya 255 de la sura Al-Baqara."),
"quran_169": ("¿Qué significa «An-Nur», título de la sura 24?", ["La luz", "La noche", "El viento", "La montaña"], "An-Nur significa «la luz»."),
"quran_170": ("¿Qué sura se llama «El Misericordioso»?", ["Ar-Rahman", "Al-Mulk", "Al-Fath", "As-Saff"], "La sura 55 se llama Ar-Rahman."),
"quran_171": ("¿Qué sura lleva el nombre de la caverna?", ["Al-Kahf", "Al-Fil", "An-Naml", "Al-Baqara"], "Al-Kahf significa «la caverna»."),
"quran_172": ("¿Qué significa «An-Nisa», título de la sura 4?", ["Las mujeres", "Los hombres", "Los niños", "Los viajeros"], "An-Nisa significa «las mujeres»."),
"quran_173": ("¿Qué significa «Al-Ma'ida», título de la sura 5?", ["La mesa servida", "La montaña", "El hierro", "El alba"], "Al-Ma'ida significa «la mesa servida»."),
"quran_174": ("¿Qué profeta da su nombre a la sura 71?", ["Nuh", "Hud", "Yunus", "Ibrahim"], "La sura 71 se llama Nuh."),
"quran_175": ("¿Cuántas aleyas tiene la sura Al-Fatiha?", ["Siete", "Tres", "Diez", "Veinte"], "Al-Fatiha tiene siete aleyas."),
"quran_176": ("¿Dónde dice el Corán que está preservado?", ["En una Tabla Protegida", "En una cueva", "En un cofre", "En una montaña"], "«Es un Corán glorioso, en una Tabla Protegida» (85:21-22)."),
"quran_177": ("¿Qué sura lleva el nombre de la luna?", ["Al-Qamar", "Ash-Shams", "An-Naym", "Al-Layl"], "Al-Qamar significa «la luna»."),
"quran_178": ("¿Qué sura lleva el nombre del Día de la Resurrección?", ["Al-Qiyama", "Al-Fath", "Al-Hashr", "As-Saff"], "La sura 75 se llama Al-Qiyama."),
"quran_179": ("¿Qué profeta da su nombre a la sura 14?", ["Ibrahim", "Muhammad ﷺ", "Yusuf", "Hud"], "La sura 14 se llama Ibrahim."),
"quran_180": ("¿Qué significa «Al-Hadid», título de la sura 57?", ["El hierro", "El oro", "La madera", "La piedra"], "Al-Hadid significa «el hierro»."),
"virtues_101": ("¿Cómo nos dice el Corán que hablemos a nuestros padres?", ["Con palabras respetuosas, sin decirles ni siquiera «uf»", "Más alto que ellos", "Quedándonos siempre callados", "Solo los viernes"], "«No les digas “uf”, y háblales con palabras nobles» (17:23)."),
"virtues_102": ("¿Cómo se llama un regalo que se da libremente, por bondad?", ["Sadaqa", "Zakat", "Tawaf", "Adhan"], "La sadaqa es la caridad voluntaria, pequeña o grande."),
"virtues_103": ("¿Qué aconseja el Profeta ﷺ sobre el hablar, a quien cree en Allah y en el Último Día?", ["Que diga algo bueno o que calle", "Que hable mucho", "Que no hable nunca", "Que hable solo con su familia"], "«Quien crea en Allah y en el Último Día, que diga el bien o que calle.»"),
"virtues_104": ("¿Cómo nos dijo el Profeta ﷺ que tratemos a nuestro vecino?", ["Ser generosos con él", "Evitarlo", "No hablarle nunca", "Pedirle que se vaya"], "«Quien crea en Allah y en el Último Día, que sea generoso con su vecino.»"),
"virtues_105": ("¿Con quién está Allah, según el Corán?", ["Con los pacientes", "Con los más ricos", "Con los más fuertes", "Con los más rápidos"], "«Ciertamente, Allah está con los pacientes» (2:153)."),
"virtues_106": ("¿Qué prohíbe el Corán hacerle al huérfano?", ["Tratarlo con dureza", "Enseñarle a leer", "Invitarlo a comer", "Jugar con él"], "«En cuanto al huérfano, no lo maltrates» (93:9)."),
"virtues_107": ("¿Qué tipo de palabras nos dice el Corán que evitemos?", ["Las palabras falsas", "Las palabras amables", "Las palabras de agradecimiento", "Las palabras de saludo"], "«Y evitad las palabras falsas» (22:30)."),
"virtues_108": ("Junto al pariente cercano, ¿a quiénes nos dice el Corán que demos lo que les corresponde?", ["Al pobre y al viajero", "Al rey y al juez", "Al comerciante", "Al poeta"], "«Da al pariente lo que le corresponde, y también al pobre y al viajero» (17:26)."),
"virtues_109": ("¿Qué promete Allah a quien Le agradece?", ["Darle más", "Hacerlo viajar", "Hacerlo famoso", "Hacerlo rey"], "«Si sois agradecidos, os daré más» (14:7)."),
"virtues_110": ("¿Cómo se dice «paciencia» en árabe?", ["As-sabr", "Ash-shukr", "As-sidq", "Al-haya'"], "As-sabr es la firmeza en la dificultad y en la obediencia."),
"faith_191": ("¿Cómo se llama recordar a Allah repitiendo Su alabanza?", ["Dhikr", "Hayy", "Sa'i", "Tayammum"], "El dhikr es el recuerdo de Allah con la lengua y con el corazón."),
"faith_192": ("¿Cuál es el primer mes del año islámico?", ["Muharram", "Ramadán", "Shawwal", "Rayab"], "El año de la Hégira comienza con el mes de Muharram."),
"faith_193": ("¿Cómo se llama volver a Allah después de un pecado?", ["Tawba", "Tawaf", "Taywid", "Tarawih"], "La tawba es el arrepentimiento: lamentar, dejar de hacerlo y volver a Allah."),
"faith_194": ("¿Quién da el sustento a cada criatura de la tierra?", ["Allah", "Los reyes", "Los comerciantes", "Los ángeles"], "«No hay criatura en la tierra cuyo sustento no dependa de Allah» (11:6)."),
"faith_195": ("¿En qué ciudad se realiza la peregrinación?", ["En La Meca", "En Medina", "En Jerusalén", "En El Cairo"], "El hayy se realiza en La Meca y en sus lugares sagrados."),
"faith_196": ("¿Cómo se llama a quien realiza la peregrinación?", ["Un hayy (peregrino)", "Un imam", "Un qari'", "Un almuédano"], "Al peregrino se le llama hayy."),
"faith_197": ("¿Qué conoce Allah, según el Corán, aunque esté oculto?", ["Lo que hay en los corazones", "Solo las obras visibles", "Solo las palabras dichas", "Nada de lo oculto"], "«Tanto si ocultáis lo que hay en vuestros pechos como si lo mostráis, Allah lo sabe» (3:29)."),
"faith_198": ("¿A quiénes se prescribió el ayuno, según el Corán?", ["A los creyentes, como a quienes los precedieron", "Solo a los viajeros", "Solo a los sabios", "Solo a los niños"], "«¡Oh creyentes! Se os ha prescrito el ayuno como se prescribió a quienes os precedieron» (2:183)."),
"faith_199": ("¿Cómo se llama la gran oración comunitaria del viernes?", ["Salat al-yumu'a", "Salat al-eid", "Salat al-witr", "Salat ad-duha"], "Salat al-yumu'a reúne a los musulmanes el viernes al mediodía."),
"faith_200": ("¿Cómo se dice «ayuno» en árabe?", ["As-sawm", "As-salat", "Az-zakat", "Al-adhan"], "As-sawm es el ayuno, el cuarto pilar del islam."),
}
